from collections import defaultdict, deque

def bfs(graph, start):
    visited = [False] * len(graph)
    queue = deque([(start, 0)])
    visited[start] = True
    max_length = 0
    max_sum = start

    while queue:
        vertex, current_sum = queue.popleft()
        for neighbor in graph[vertex]:
            if not visited[neighbor]:
                visited[neighbor] = True
                new_sum = current_sum + neighbor
                queue.append((neighbor, new_sum))
                if new_sum > max_sum:
                    max_sum = new_sum
                    max_length = current_sum + 1

    return max_length, max_sum

def solve_test_case(N, edges):
    graph = defaultdict(list)
    for x, y in edges:
        graph[x].append(y)
        graph[y].append(x)

    S = [0] * (N + 1)
    for i in range(1, N + 1):
        if not graph[i]:
            S[i] = i
        else:
            max_length, max_sum = bfs(graph, i)
            S[i] = max_sum

    A = min(S)
    B = max(S)

    # Find the minimum values of x and y such that Ax = By
    for x in range(1, 1001):
        for y in range(1, 1001):
            if A * x == B * y:
                return x, y

def main():
    T = int(input())
    results = []
    for _ in range(T):
        N, M = map(int, input().split())
        edges = [list(map(int, input().split())) for _ in range(M)]
        x, y = solve_test_case(N, edges)
        results.append((x, y))

    for result in results:
        print(*result)

if __name__ == "__main__":
    main()
